// Control Rig units of the animation plugin (presentation only).

#include "GSTN_RigUnit_LimbContactIK.h"

#include "GSTN_LimbContactUtils.h"
#include "Rigs/RigHierarchy.h"
#include "TwoBoneIK.h"
#include "Units/RigUnitContext.h"

#include UE_INLINE_GENERATED_CPP_BY_NAME(GSTN_RigUnit_LimbContactIK)

namespace GSTNLimbContactRig
{
	/** Under this weight the node leaves the pose untouched (no IK solve, no rounding drift) */
	constexpr float MinAppliedAlpha = 1.e-3f;
}

// Body of Execute(): the macro is generated by UHT for RIGVM_METHOD, as in the engine units
FGSTN_RigUnit_LimbContactIK_Execute()
{
	URigHierarchy* Hierarchy = ExecuteContext.Hierarchy;
	if (!Hierarchy)
	{
		return;
	}

	// A missing bone (another skeleton, a typo) leaves the limb animated: Alpha stays 0 so the debug output shows it
	if (!CachedRoot.UpdateCache(Root, Hierarchy) || !CachedJoint.UpdateCache(Joint, Hierarchy) || !CachedEffector.UpdateCache(Effector, Hierarchy))
	{
		SmoothedAlpha = 0.f;
		Alpha = 0.f;
		return;
	}

	FTransform RootTransform = Hierarchy->GetGlobalTransform(CachedRoot.GetIndex());
	FTransform JointTransform = Hierarchy->GetGlobalTransform(CachedJoint.GetIndex());
	FTransform EffectorTransform = Hierarchy->GetGlobalTransform(CachedEffector.GetIndex());

	const FVector RootLocation = RootTransform.GetLocation();
	const FVector JointLocation = JointTransform.GetLocation();
	const FVector EffectorLocation = EffectorTransform.GetLocation();
	const float ChainLength = FVector::Dist(RootLocation, JointLocation) + FVector::Dist(JointLocation, EffectorLocation);

	const FGSTN_LimbContactResult Contact = UGSTN_LimbContactUtils::ComputeContact(EffectorLocation, RootLocation, ChainLength, Surface, Settings);
	SmoothedAlpha = UGSTN_LimbContactUtils::StepContactAlpha(SmoothedAlpha, Contact.TargetAlpha * FMath::Clamp(Weight, 0.f, 1.f), Settings, ExecuteContext.GetDeltaTime());
	Alpha = SmoothedAlpha;
	Target = Contact.TargetLocation;

	if (Alpha < GSTNLimbContactRig::MinAppliedAlpha)
	{
		return;
	}

	const FVector Goal = FMath::Lerp(EffectorLocation, Contact.TargetLocation, Alpha);
	const FQuat EffectorRotation = UGSTN_LimbContactUtils::AlignAxisToSurface(EffectorTransform.GetRotation(), Settings.ContactAxis, Surface.Normal,
		Settings.RotationAlpha * Alpha);

	// The animated joint location is the pole: the clip keeps deciding which way the elbow or knee bends. No stretching: a goal out of
	// reach was already rejected by MaxReachRatio, and a stretched limb would change the silhouette
	AnimationCore::SolveTwoBoneIK(RootTransform, JointTransform, EffectorTransform, JointLocation, Goal, false, 1.0, 1.0);
	EffectorTransform.SetRotation(EffectorRotation);

	// Parent first, each one carrying its children (fingers and toes follow the effector)
	Hierarchy->SetGlobalTransform(CachedRoot.GetIndex(), RootTransform, false, true);
	Hierarchy->SetGlobalTransform(CachedJoint.GetIndex(), JointTransform, false, true);
	Hierarchy->SetGlobalTransform(CachedEffector.GetIndex(), EffectorTransform, false, true);
}
